    const object = await r2.get(`${prefix}result.json`);
    if (!object) continue;

    const result = (await object.json()) as DbtRunResult;
    summaries.push({
      runId: result.runId,
      startedAt: result.startedAt,
      completedAt: result.completedAt,
      success: result.success,
    });
